<template>
  <section class="po-replay" data-test="po-replay-player">
    <p v-if="replay.reason" role="status" data-test="po-replay-unavailable">
      {{ $t(`po_replay_unavailable_${replay.reason}`) }}
    </p>
    <template v-else>
      <p class="po-replay__note">{{ $t('po_replay_historical') }}</p>
      <dl class="po-replay__facts">
        <div>
          <dt>{{ $t('po_replay_recorded_at') }}</dt>
          <dd>{{ recordedAt || '—' }}</dd>
        </div>
        <div>
          <dt>{{ $t('po_match_ruleset_version') }}</dt>
          <dd>{{ replay.version || '—' }}</dd>
        </div>
        <div>
          <dt>{{ $t('po_replay_hash') }}</dt>
          <dd>{{ replay.hash || '—' }}</dd>
        </div>
      </dl>
      <p
        v-if="replay.basis !== 'same'"
        class="po-replay__warning"
        data-test="po-replay-basis"
      >
        {{ $t(`po_replay_basis_${replay.basis}`) }}
      </p>
      <p v-if="documentChanged" class="po-replay__warning" role="status">
        {{ $t('po_replay_document_changed') }}
      </p>
      <p v-if="reducedMotion" class="po-replay__note">
        {{ $t('po_replay_reduced_motion') }}
      </p>
      <div
        class="po-replay__controls"
        role="group"
        :aria-label="$t('po_replay_controls')"
      >
        <button
          type="button"
          data-test="po-replay-play"
          :disabled="reducedMotion"
          @click="togglePlay"
        >
          {{ $t(playing ? 'po_replay_pause' : 'po_replay_play') }}
        </button>
        <button type="button" :disabled="index < 0" @click="move(-1)">
          {{ $t('po_replay_previous') }}
        </button>
        <button type="button" :disabled="finished" @click="move(1)">
          {{ $t('po_replay_next') }}
        </button>
        <button type="button" @click="reset">
          {{ $t('po_replay_reset') }}
        </button>
        <label
          >{{ $t('po_replay_speed') }}
          <select v-model.number="speed">
            <option :value="0.5">0.5×</option>
            <option :value="1">1×</option>
            <option :value="2">2×</option>
          </select>
        </label>
        <span aria-live="polite">{{
          $t('po_replay_position', {
            current: index + 1,
            total: replay.steps.length,
          })
        }}</span>
      </div>
      <div class="po-replay__workspace">
        <aside class="po-replay__details">
          <div
            class="po-replay__step"
            aria-live="polite"
            aria-atomic="true"
            data-test="po-replay-step"
          >
            <template v-if="current?.kind === 'outcome'">
              <h3>{{ $t(`po_replay_result_${replay.result}`) }}</h3>
              <dl class="po-replay__facts">
                <div>
                  <dt>{{ $t('po_replay_matched_groups') }}</dt>
                  <dd>{{ replay.matched ?? '—' }}</dd>
                </div>
                <div>
                  <dt>{{ $t('po_replay_open_po') }}</dt>
                  <dd>{{ replay.openPo ?? '—' }}</dd>
                </div>
                <div>
                  <dt>{{ $t('po_replay_open_table') }}</dt>
                  <dd>{{ replay.openTable ?? '—' }}</dd>
                </div>
              </dl>
              <p>{{ $t('po_replay_not_exported') }}</p>
            </template>
            <template v-else-if="current?.stage">
              <h3>
                {{ current.stage.no }} · {{ text(current.stage.label)
                }}<template v-if="current.pass">
                  · {{ text(current.pass.label) }}</template
                >
              </h3>
              <p>{{ stateLabel }}</p>
              <dl class="po-replay__facts">
                <template v-if="current.pass && current.pass.state !== 'skip'">
                  <div>
                    <dt>{{ $t('po_replay_pairs') }}</dt>
                    <dd>{{ count(current.pass.pairs_evaluated) ?? '—' }}</dd>
                  </div>
                  <div>
                    <dt>{{ $t('po_replay_matched_groups') }}</dt>
                    <dd>{{ count(current.pass.matched) ?? '—' }}</dd>
                  </div>
                </template>
                <template
                  v-if="
                    current.kind === 'stage' && current.stage.state !== 'skip'
                  "
                >
                  <div>
                    <dt>{{ $t('po_replay_groups_after') }}</dt>
                    <dd>
                      {{ count(current.stage.matched_after_stage) ?? '—' }}
                    </dd>
                  </div>
                  <div>
                    <dt>{{ $t('po_replay_open_po') }}</dt>
                    <dd>
                      {{ count(current.stage.pending_po_lines_after) ?? '—' }}
                    </dd>
                  </div>
                  <div>
                    <dt>{{ $t('po_replay_open_table') }}</dt>
                    <dd>
                      {{
                        count(current.stage.pending_table_lines_after) ?? '—'
                      }}
                    </dd>
                  </div>
                </template>
              </dl>
              <p v-if="attemptRules.length">
                {{ $t('po_replay_recorded_rules') }}:
                {{ attemptRules.join(', ') }}
              </p>
            </template>
            <p v-else>{{ $t('po_replay_ready') }}</p>
          </div>
          <div
            v-if="current?.pass?.failed_columns.length"
            class="po-replay__failures"
          >
            <h4>{{ $t('po_replay_failed_columns') }}</h4>
            <article
              v-for="(column, i) in current.pass.failed_columns"
              :key="i"
              class="po-replay__failure"
            >
              <strong>{{ column.column_key || column.column || '—' }}</strong>
              <p>{{ $t('po_replay_rule') }}: {{ column.rule || '—' }}</p>
              <dl class="po-replay__comparison">
                <div>
                  <dt>{{ $t('po_replay_expected') }}</dt>
                  <dd>{{ column.expected ?? '—' }}</dd>
                </div>
                <div>
                  <dt>{{ $t('po_replay_actual') }}</dt>
                  <dd>{{ column.actual ?? '—' }}</dd>
                </div>
                <div>
                  <dt>{{ $t('po_replay_tolerance') }}</dt>
                  <dd>
                    {{ column.tolerance ?? '—' }}
                    {{ column.tolerance_type || '' }}
                  </dd>
                </div>
              </dl>
            </article>
          </div>
        </aside>
        <div ref="diagram" class="po-replay__diagram">
          <PoMatchDecisionFlow
            :stages="displayStages"
            :transformation="replay.transformation"
            mode="document"
            replay
            :replay-focus="focus"
            :animate-replay="animate"
            @select-pass="selectPass"
          />
        </div>
      </div>
    </template>
  </section>
</template>

<script setup lang="ts">
import {
  computed,
  getCurrentInstance,
  onBeforeUnmount,
  onMounted,
  ref,
  watch,
} from 'vue';
import {
  pickPoMatchText,
  type PoMatchText,
} from 'src/services/analytics/PoMatchExplanationService';
import {
  buildPoReplay,
  replayCount,
  replayStagesAt,
} from 'src/utils/po-match-replay';
import PoMatchDecisionFlow from './PoMatchDecisionFlow.vue';

const props = defineProps<{
  response: unknown;
  docId: string;
  documentChanged?: boolean;
}>();
const instance = getCurrentInstance();
const t = (key: string) => String(instance?.proxy?.$t(key) ?? key);
const locale = computed(() => {
  const i18n = instance?.proxy?.$i18n;
  return i18n && 'locale' in i18n ? String(i18n.locale || 'en') : 'en';
});
const text = (value?: PoMatchText | null) =>
  pickPoMatchText(value, locale.value);
const count = replayCount;
const replay = computed(() => buildPoReplay(props.response, props.docId));
const index = ref(-1);
const playing = ref(false);
const speed = ref(1);
const animate = ref(false);
const reducedMotion = ref(false);
const diagram = ref<HTMLElement | null>(null);
let timer: ReturnType<typeof setTimeout> | undefined;
let media: MediaQueryList | undefined;
const current = computed(() => replay.value.steps[index.value]);
const finished = computed(() => index.value >= replay.value.steps.length - 1);
const displayStages = computed(() => replayStagesAt(replay.value, index.value));
const focus = computed(() =>
  current.value?.stage
    ? { stage: current.value.stage.key, pass: current.value.pass?.key ?? null }
    : null,
);
const recordedAt = computed(() =>
  replay.value.evaluatedAt
    ? new Date(replay.value.evaluatedAt).toLocaleString(locale.value)
    : '',
);
const attemptRules = computed(() => [
  ...new Set(
    (current.value?.pass?.attempts || [])
      .map((item) => item.rule)
      .filter(Boolean),
  ),
]);
const stateLabel = computed(() => {
  const subject = current.value?.pass || current.value?.stage;
  if (!subject) return '';
  if (subject.state === 'skip')
    return `${t('po_replay_skip')} · ${text(subject.skipped_reason_label) || t('po_replay_reason_unknown')}`;
  return t(
    current.value?.kind === 'stage'
      ? 'po_replay_stage_complete'
      : subject.state === 'pass'
        ? 'po_replay_pass_match'
        : 'po_replay_pass_no_match',
  );
});
function pause() {
  playing.value = false;
  clearTimeout(timer);
  timer = undefined;
  animate.value = false;
}
function reset() {
  pause();
  index.value = -1;
}
function move(delta: number) {
  pause();
  index.value = Math.max(
    -1,
    Math.min(replay.value.steps.length - 1, index.value + delta),
  );
}
function schedule() {
  clearTimeout(timer);
  if (!playing.value) return;
  timer = setTimeout(() => {
    if (document.hidden || reducedMotion.value || replay.value.reason) {
      pause();
      return;
    }
    animate.value = true;
    index.value += 1;
    if (finished.value) {
      playing.value = false;
      timer = undefined;
    } else schedule();
  }, 1400 / speed.value);
}
function togglePlay() {
  if (playing.value) {
    pause();
    return;
  }
  if (replay.value.reason || reducedMotion.value || document.hidden) return;
  if (finished.value) index.value = -1;
  playing.value = true;
  if (index.value < 0) index.value = 0;
  if (finished.value) pause();
  else schedule();
}
function selectPass(value: { stage: string; pass: string }) {
  let target = replay.value.steps.findIndex(
    (step) => step.stage?.key === value.stage && step.pass?.key === value.pass,
  );
  if (target < 0) {
    target = replay.value.steps.findIndex(
      (step) =>
        step.kind === 'stage' &&
        step.stage?.key === value.stage &&
        step.stage.state === 'skip',
    );
  }
  if (target >= 0) {
    pause();
    index.value = target;
  }
}
function visibilityChanged() {
  if (document.hidden) pause();
}
function motionChanged() {
  reducedMotion.value = media?.matches ?? false;
  if (reducedMotion.value) pause();
}
watch(() => [props.response, props.docId], reset);
watch(() => props.documentChanged, pause);
watch(speed, () => {
  if (playing.value) schedule();
});
// Move only the diagram's own viewport, never the surrounding matching screen.
// Instant scrolling also keeps manual keyboard steps and reduced motion motion-free.
watch(
  index,
  () => {
    const viewport = diagram.value;
    if (!viewport) return;
    if (index.value < 0) {
      viewport.scrollTop = 0;
      return;
    }
    const target = viewport.querySelector('[data-replay-active="true"]');
    if (!target) return;
    const outer = viewport.getBoundingClientRect();
    const box = target.getBoundingClientRect();
    if (box.top < outer.top + 16 || box.bottom > outer.bottom - 16)
      viewport.scrollTop += box.top - outer.top - 24;
    const horizontal = viewport.querySelector<HTMLElement>('.pmdf__scroll');
    if (horizontal) {
      const bounds = horizontal.getBoundingClientRect();
      if (box.left < bounds.left || box.right > bounds.right)
        horizontal.scrollLeft += box.left - bounds.left - 24;
    }
  },
  { flush: 'post' },
);
onMounted(() => {
  media = window.matchMedia?.('(prefers-reduced-motion: reduce)');
  motionChanged();
  media?.addEventListener?.('change', motionChanged);
  document.addEventListener('visibilitychange', visibilityChanged);
});
onBeforeUnmount(() => {
  pause();
  media?.removeEventListener?.('change', motionChanged);
  document.removeEventListener('visibilitychange', visibilityChanged);
});
</script>

